import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<void> _initFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;

  bool _hasMore = true;

  bool _isLoadingNext = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_initFuture == null) {
      _initFuture = _initData();
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _refreshAll();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _initData() async {
    final currencyRepository = context.read<CurrencyRepository>();

    _currentPage = 0;
    _allCurrencies.clear();
    _filteredCurrenciesNotifier = ValueNotifier(const []);
    _hasMore = true;
    _isLoadingNext = false;

    await _loadPage(currencyRepository, isFirstLoad: true);
  }

  Future<void> _loadPage(
    CurrencyRepository repository, {
    bool isFirstLoad = false,
  }) async {
    final page = await repository.fetchRates(
      CurrencyPageRequest(base: 'USD', page: _currentPage),
    );

    if (isFirstLoad) {
      setState(() {
        _allCurrencies = page.items;
        _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies);
        _hasMore = page.hasMore;
      });
      _fadeController.forward();
      await repository.saveCurrencyList(page.items);
    } else {
      setState(() {
        _allCurrencies.addAll(page.items);
        _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies);
        _hasMore = page.hasMore;
        _isLoadingNext = false;
      });
      await repository.saveCurrencyList(page.items);
    }

    if (page.hasMore && mounted) {
      _currentPage++;
    }
  }

  Future<void> _loadMore() async {
    if (!_hasMore || _isLoadingNext) return;
    _isLoadingNext = true;
    final currencyRepository = context.read<CurrencyRepository>();
    await _loadPage(currencyRepository);
  }

  Future<void> _refreshAll() async {
    if (!mounted) return;
    setState(() {
      _fadeController.reset();
    });
    await _initData();
    // Перезапускаем future для FutureBuilder, чтобы не показывало лоадер повторно.
    final newFuture = _loadPage(context.read<CurrencyRepository>());

    // Не перезаписываем _initFuture — он уже завершён и FutureBuilder не перестроится.
    // Данные уже обновлены через setState в _loadPage.
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where(
      (CurrencyModel currency) {
        return currency.name.toLowerCase().contains(lowerQuery) ||
            currency.symbol.toLowerCase().contains(lowerQuery);
      },
    );

    _filteredCurrenciesNotifier.value = List.unmodifiable(result.toList(growable: false));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<void>(
        future: _initFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState != ConnectionState.done) {
            return const Center(child: CircularProgressIndicator());
          }

          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                child: SearchView(onChanged: _filterCurrencies),
              ),
              Expanded(
                child: ValueListenableBuilder<List<CurrencyModel>>(
                  valueListenable: _filteredCurrenciesNotifier,
                  builder: (BuildContext context, List<CurrencyModel> data, _) {
                    return ListView.builder(
                      itemCount: _hasMore ? data.length + 1 : data.length,
                      itemBuilder: (BuildContext context, int index) {
                        if (index == data.length && _hasMore) {
                          return Padding(
                            padding: const EdgeInsets.only(top: 10),
                            child: Center(
                              child: ElevatedButton(
                                onPressed: _isLoadingNext ? null : _loadMore,
                                child: Text(context.loc.showMore),
                              ),
                            ),
                          );
                        }

                        final CurrencyModel currency = data[index];

                        return Padding(
                          key: ValueKey(currency.id),
                          padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                          child: CurrencyCard(model: currency),
                        );
                      },
                      padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                    );
                  },
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

